# A TUPLE RATHER THAN A LIST, and that is what the error state is built on: folding an unreadable
# answer into an empty one leaves a block telling a reader that nothing is published when the truth
# is that nothing could be read.
case result do
  {:ok, %{results: found, count: count}} -> {:ok, %{rows: found, total: count || length(found)}}
  {:ok, found} when is_list(found) -> {:ok, %{rows: found, total: length(found)}}
  {:error, reason} -> {:error, reason}
  _unreadable -> {:error, :unreadable}
end

# THE ROWS, AND NOTHING THE PAGE ALREADY KNOWS. Run in a task on a live visit, so nothing here may
# touch the socket, and answered in the shape `stream_async` takes: `{:ok, rows, opts}` or
# `{:error, reason}`. `reset` replaces the cards of the page the reader was on with these.
with {:ok, %{rows: documents}} <- documents_page(asked) do
  editions =
    ((asked.show_languages or asked.show_details) && editions_of(documents, asked.visitor)) || %{}

  details = (asked.show_details && details_of(documents, editions, asked.visitor)) || %{}

  {:ok, rowed(asked, documents, editions, details), reset: true}
end

# THE VERSION IS IN THE URL ONLY WHILE IT IS NOT THE LATEST ONE. Carrying ?v=0.0.6 around a document
# whose latest version is 0.0.6 pins every link a reader shares to a number that will be old next
# week, and the same page then reads as an archived one.
key = trimmed(version_param)

case {version, latest} do
  {nil, _no_versions} -> %{}
  {_asked, nil} -> %{}
  {%{id: same}, %{id: same}} -> %{}
  {%{version_number: number}, _older} when key != "" -> %{key => to_string(number)}
  _no_key_to_write_it_under -> %{}
end

case section do
  nil ->
    {nil, nil}

  %{id: id} ->
    case Enum.find_index(sections, &(&1.id == id)) do
      nil -> {nil, nil}
      0 -> {nil, Enum.at(sections, 1)}
      found -> {Enum.at(sections, found - 1), Enum.at(sections, found + 1)}
    end
end

case socket.assigns.extras.asked == asked do
  false -> {:noreply, socket}
  true -> {:noreply, Phoenix.Component.assign(socket, :extras, unfetched(socket.assigns.extras))}
end

# WHAT NEVER ARRIVED SAYS SO: each tab still being fetched says its `failed_text`, and the header's
# skeleton is taken away.
%{
  extras
  | header: Enum.reject(extras.header, &(&1.kind == :pending)),
    tabs:
      Enum.map(extras.tabs, fn
        %{state: :not_ready} = tab -> %{tab | state: :failed, text: tab.failed_text || tab.text}
        tab -> tab
      end),
    pending: []
}

# ONE CELL, read under its column's key: a list is drawn as its items, a map with `text` as a badge
# in its tone, any other word as text — in code where the column says so — and nothing as blank.
case Map.get(row, column.key) do
  items when is_list(items) ->
    case Enum.flat_map(items, &List.wrap(plain(&1))) do
      [] -> %{kind: :blank, column: column.key}
      words -> %{kind: :items, column: column.key, items: words}
    end

  %{text: text} = badge ->
    case plain(text) do
      nil -> %{kind: :blank, column: column.key}
      word -> %{kind: :badge, column: column.key, text: word, tone: tone_of(Map.get(badge, :tone))}
    end

  value ->
    case plain(value) do
      nil -> %{kind: :blank, column: column.key}
      word -> %{kind: :text, column: column.key, text: word, code: column.code}
    end
end

