# `open_tab` and carries the address of the page with that tab in its URL, `data-href`, which the
# `doc-tabs` hook writes into the address bar. The one shown is `aria-current`.
~H"""
<nav
  id={"#{@id}-tabs"}
  phx-hook={tabs_hook()}
  data-role="doc-tabs"
  aria-label={@tabs_label}
  class="mt-5 mb-5 flex gap-1 overflow-x-auto border-b border-[#ecebe6]"
>
  <button
    type="button"
    id={"#{@id}-tab-documentation"}
    phx-click="open_tab"
    phx-value-tab=""
    phx-target={@target}
