    data-tab="documentation"
    data-href={@extras.docs_href}
    aria-current={@open == "" && "page"}
    class={[
      "-mb-px shrink-0 cursor-pointer whitespace-nowrap border-b-2 px-4 py-2 text-sm font-semibold",
      tab_class(@open == "")
    ]}
  >
    {@docs_tab_text}
  </button>
  <button
    :for={tab <- @extras.tabs}
    type="button"
    id={"#{@id}-tab-#{tab.id}"}
    phx-click="open_tab"
    phx-value-tab={tab.id}
    phx-target={@target}
    data-role="doc-tab"
    data-tab={tab.id}
    data-href={tab.href}
    aria-current={@open == tab.id && "page"}
    class={[
      "-mb-px shrink-0 cursor-pointer whitespace-nowrap border-b-2 px-4 py-2 text-sm font-semibold",
      tab_class(@open == tab.id)
    ]}
  >
    {tab.label}
  </button>
</nav>
