// Copies a documentation code block's code when the button on its window is pressed.
//
// `doc-section` mounts this on its own root, outside the page's text, and draws every code block of
// that text in a `[data-role="doc-code"]` window with a `[data-role="doc-code-copy"]` button, and
// each command a plugin puts on the page in a `[data-role="doc-extra-command"]` with the same button.
// One listener on the root answers every button inside it, so a button a later render draws is
// answered as well as the first.
//
// The code is the text of the window's `<pre><code>` — or of its `<pre>`, or of the command's
// `<code>` — written with the Clipboard API, or through a textarea and `execCommand("copy")` where
// that API is missing or refused. Once it is copied the button carries `data-copied="true"` for
// COPIED_FOR milliseconds, for a stylesheet to draw, and the window's `[data-role="doc-code-status"]`
// reads the button's `data-copied-text` out to a screen reader. No class and no style attribute is
// written.
//
// A code window doc-section marks `data-collapsible` is cut at its `data-collapse-lines` until the
// `[data-role="doc-code-expand"]` button under its code shows all of it — the same listener answers
// it. The choice is `data-expanded` on the window and `aria-expanded` on the button, written through
// the hook's JS commands so a LiveView patch keeps them; folding a window whose top has left the
// screen brings its top back. The copy button copies the whole code either way.
const COPIED_FOR = 1200;

const BUTTON = '[data-role="doc-code-copy"]';
const WINDOW = '[data-role="doc-code"], [data-role="doc-extra-command"]';
const STATUS = '[data-role="doc-code-status"]';
const EXPAND = '[data-role="doc-code-expand"]';
const CODE = '[data-role="doc-code"]';

function copyThroughSelection(text) {
  const area = document.createElement("textarea");
  const focused = document.activeElement;
  let copied = false;

  area.value = text;
  area.setAttribute("readonly", "");
  area.setAttribute("aria-hidden", "true");
  area.style.position = "fixed";
  area.style.top = "0";
  area.style.left = "0";
  area.style.opacity = "0";
  area.style.pointerEvents = "none";
  document.body.appendChild(area);
  area.select();

  try {
    copied = document.execCommand("copy");
  } catch (_refused) {
    copied = false;
  }

  area.remove();
  if (focused && typeof focused.focus === "function") focused.focus({ preventScroll: true });

  return copied;
}

function copyText(text) {
  if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
    return navigator.clipboard.writeText(text).then(
      () => true,
      () => copyThroughSelection(text),
    );
  }

  return Promise.resolve(copyThroughSelection(text));
}

const DocCodeCopy = {
  mounted() {
    this.timers = new Map();

    this.onClick = (event) => {
      const target = event.target instanceof Element ? event.target : null;
      const button = target && target.closest(BUTTON);
      const expand = target && target.closest(EXPAND);

      if (button && this.el.contains(button)) {
        this.copy(button);
      } else if (expand && this.el.contains(expand)) {
        this.toggle(expand);
      }
    };

    this.el.addEventListener("click", this.onClick);
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
    this.timers.forEach((timer) => clearTimeout(timer));
    this.timers.clear();
  },

  copy(button) {
    const frame = button.closest(WINDOW);
    const code =
      frame &&
      (frame.querySelector("pre code") || frame.querySelector("pre") || frame.querySelector("code"));
    if (!code) return;

    copyText(code.textContent).then((copied) => {
      if (copied) this.flash(button, frame);
    });
  },

  toggle(expand) {
    const frame = expand.closest(CODE);
    if (!frame) return;

    const js = this.js();

    if (frame.hasAttribute("data-expanded")) {
      js.removeAttribute(frame, "data-expanded");
      js.setAttribute(expand, "aria-expanded", "false");
      if (frame.getBoundingClientRect().top < 0) frame.scrollIntoView({ block: "start" });
    } else {
      js.setAttribute(frame, "data-expanded", "true");
      js.setAttribute(expand, "aria-expanded", "true");
    }
  },

  flash(button, frame) {
    const status = frame.querySelector(STATUS);

    clearTimeout(this.timers.get(button));
    button.setAttribute("data-copied", "true");
    if (status) status.textContent = button.getAttribute("data-copied-text") || "";

    this.timers.set(
      button,
      setTimeout(() => {
        this.timers.delete(button);
        button.removeAttribute("data-copied");
        if (status) status.textContent = "";
      }, COPIED_FOR),
    );
  },
};

export default DocCodeCopy;

// Answers a documentation example's toolbar: draws the example on the page left to right or right to
// left, opens its preview, and switches the preview between its colours, widths and directions.
//
// `doc-example` mounts this on its own root. The example itself is drawn on the page, in the root's
// `[data-role="doc-example-stage"]`, so its components' own hooks, events and popups work there as
// anywhere on the page. The toolbar's `[data-role="doc-example-option"]` buttons name what they
// switch in `data-action` — theme, device or dir — and the choice in `data-value`; the
// `[data-role="doc-example-open"]` button opens the preview, a `<dialog>`
// (`[data-role="doc-example-preview"]`) holding a `[data-role="doc-example-frame"]` iframe, and its
// `[data-role="doc-example-close"]` button, Escape and a press on the backdrop close it.
//
// One listener on the root answers every button. A press writes the choice onto the root as
// `data-frame-theme`, `data-frame-device` or `data-frame-dir`, and `aria-pressed` onto that
// action's buttons, through the hook's own JS commands, which a LiveView patch keeps. A direction is
// also the stage's `dir`, so the example on the page turns with it.
//
// The preview is built the first time it opens, inside the root's
// `[data-role="doc-example-preview-holder"]` — an element LiveView leaves to the browser, so a patch
// never closes or takes it away. The holder carries what the preview says: `data-label` its name and
// title, `data-toolbar-label` its toolbar's name, `data-frame-label` its frame's, `data-light-text`,
// `data-dark-text`, `data-desktop-text`, `data-tablet-text`, `data-mobile-text`, `data-ltr-text`,
// `data-rtl-text` and `data-close-text` its buttons', and `data-src` the page its frame shows; its
// buttons start pressed as the root's `data-frame-*` say. Every part says what it is in its
// `data-role`, which is all the kit's stylesheet draws it by: no class and no style attribute is
// written.
//
// The preview is the example drawn live, alone, on a page of its own: the frame's `data-src` names
// it — `/_preview/doc-example/…`, which draws the example with the site's stylesheet and scripts, so
// its menus, tabs, flashes and forms work there as on the page. The frame is handed it as its `src`
// only when the preview opens, so the page around the example loads nothing for it before; and when
// the preview closes, however it is closed, the frame's `src` is taken away and its page sent to
// `about:blank`, so nothing keeps running behind a closed preview. The frame's page is same-origin,
// so this hook dresses it from outside: the theme as its `<html data-theme>` and the direction as its
// `<html dir>`, once it has loaded and after every choice, without loading it again. The frame is
// kept hidden, through its CSSOM `visibility`, until its page has loaded and been dressed.
//
// The frame is as wide as the device it is drawn for — 1280, 768 or 375 pixels, its `width`
// attribute — and as tall as the example in its page or as the preview's stage, whichever is
// taller, its `height` attribute, so a toast or a dialog the example opens has the stage to open in;
// a frame wider than the preview is scaled down to fit it, through the frame's and its
// `[data-role="doc-example-viewport"]`'s CSSOM style — a property set from script, never a style
// attribute, so no CSP refuses it. It is measured again whenever the example's
// `[data-role="doc-example-live"]` changes size, as an observer of the frame page's own window sees
// it, when its fonts arrive, when the preview's size changes and after every choice. A link pressed
// inside the frame that leads to another page closes the preview and leads the page itself there,
// never the frame; one that only moves within the page, or that an example answers itself, is left
// to the example.
//
// An example taller than the root's `data-collapse-height` pixels is cut at that height until the
// `[data-role="doc-example-expand"]` button under it shows all of it: the hook writes
// `data-collapsible` onto the root each time the example's `[data-role="doc-example-body"]` changes
// size, measured by a ResizeObserver once the browser has laid the page out, so mounting reads no
// layout; and the button writes `data-expanded` onto the root and `aria-expanded` onto itself.
// Folding an example whose top has left the screen brings its top back. The cut and its fade are
// the stylesheet's, keyed on those attributes.
const OPTION = '[data-role="doc-example-option"]';
const EXPAND = '[data-role="doc-example-expand"]';
const OPEN = '[data-role="doc-example-open"]';
const CLOSE = '[data-role="doc-example-close"]';
const STAGE = '[data-role="doc-example-stage"]';
const BODY = '[data-role="doc-example-body"]';
const HOLDER = '[data-role="doc-example-preview-holder"]';
const PREVIEW = '[data-role="doc-example-preview"]';
const PREVIEW_STAGE = '[data-role="doc-example-preview-stage"]';
const VIEWPORT = '[data-role="doc-example-viewport"]';
const FRAME = '[data-role="doc-example-frame"]';
const LIVE = '[data-role="doc-example-live"]';

const CHOICES = {
  theme: ["light", "dark"],
  device: ["desktop", "tablet", "mobile"],
  dir: ["ltr", "rtl"],
};

const WIDTHS = { desktop: 1280, tablet: 768, mobile: 375 };

const SVG = "http://www.w3.org/2000/svg";

const ICONS = {
  light:
    "M12 3v2.25m6.364.386-1.591 1.591M21 12h-2.25m-.386 6.364-1.591-1.591M12 18.75V21m-4.773-4.227-1.591 1.591M5.25 12H3m4.227-4.773L5.636 5.636M15.75 12a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0Z",
