// An element of the preview, with its attributes and what it holds.
const element = (tag, attributes, children = []) => {
  const node = document.createElement(tag);
  Object.entries(attributes).forEach(([name, value]) => node.setAttribute(name, value));
  node.append(...children);
  return node;
};

const icon = (name) => {
  const svg = document.createElementNS(SVG, "svg");
  const path = document.createElementNS(SVG, "path");

  [
    ["data-role", "doc-example-icon"],
    ["aria-hidden", "true"],
    ["viewBox", "0 0 24 24"],
    ["fill", "none"],
    ["stroke", "currentColor"],
    ["stroke-width", "1.6"],
  ].forEach(([attribute, value]) => svg.setAttribute(attribute, value));

  path.setAttribute("stroke-linecap", "round");
  path.setAttribute("stroke-linejoin", "round");
  path.setAttribute("d", ICONS[name]);
  svg.append(path);
  return svg;
};

const DocExample = {
  mounted() {
    this.dressed = new WeakSet();

    this.onClick = (event) => {
      const target = event.target instanceof Element ? event.target : null;
      if (!target) return;

      const option = target.closest(OPTION);
      const expand = target.closest(EXPAND);
      const open = target.closest(OPEN);
      const close = target.closest(CLOSE);

      if (option && this.el.contains(option)) {
        this.choose(option.getAttribute("data-action"), option.getAttribute("data-value"));
      } else if (expand && this.el.contains(expand)) {
        this.toggle(expand);
      } else if (open && this.el.contains(open)) {
        this.open();
      } else if (close && this.el.contains(close)) {
        this.close();
      } else if (target.matches(PREVIEW)) {
        this.close();
      }
    };

    this.onLoad = () => this.loaded();
    this.onClosed = () => this.unload();
    this.onFollow = (event) => this.follow(event);
    this.measures =
      typeof ResizeObserver === "function"
        ? new ResizeObserver((entries) => this.measured(entries))
        : null;

    this.el.addEventListener("click", this.onClick);
    this.attach();
  },

  updated() {
    this.attach();
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
    if (this.measures) this.measures.disconnect();
    if (this.preview && this.preview.open) this.preview.close();
    this.unload();
    if (this.frame) this.frame.removeEventListener("load", this.onLoad);
    if (this.preview) this.preview.removeEventListener("close", this.onClosed);
  },

  // The parts this root holds now, listened to; a render that drew others hands them over.
  attach() {
    const body = this.el.querySelector(BODY);
    const preview = this.el.querySelector(PREVIEW);
    const frame = this.el.querySelector(FRAME);
    const stage = this.el.querySelector(PREVIEW_STAGE);

    if (body !== this.body) {
      if (this.measures && this.body) this.measures.unobserve(this.body);
      this.body = body;
      if (this.measures && body) this.measures.observe(body);
      if (!this.measures && body) this.collapse(body.getBoundingClientRect().height);
    }

    if (stage !== this.stage) {
      if (this.measures && this.stage) this.measures.unobserve(this.stage);
      this.stage = stage;
      if (this.measures && stage) this.measures.observe(stage);
    }

    if (frame !== this.frame) {
      if (this.frame) this.frame.removeEventListener("load", this.onLoad);
      this.frame = frame;
      if (frame) frame.addEventListener("load", this.onLoad);
    }

    if (preview !== this.preview) {
      if (this.preview) this.preview.removeEventListener("close", this.onClosed);
      this.preview = preview;
      if (preview) preview.addEventListener("close", this.onClosed);
    }
  },

  measured(entries) {
    entries.forEach((entry) => {
      if (entry.target === this.body) this.collapse(entry.target.getBoundingClientRect().height);
      if (entry.target === this.stage) this.fit();
    });
  },

  choose(action, value) {
    if (!(CHOICES[action] || []).includes(value)) return;

    const js = this.js();
    js.setAttribute(this.el, `data-frame-${action}`, value);

    this.el.querySelectorAll(`${OPTION}[data-action="${action}"]`).forEach((option) => {
      js.setAttribute(option, "aria-pressed", String(option.getAttribute("data-value") === value));
    });

    const stage = this.el.querySelector(STAGE);
    if (action === "dir" && stage) js.setAttribute(stage, "dir", value);

    this.dress();
  },

  // The preview, built into its holder with the words the holder carries and the choices the root
  // holds now.
  build() {
    const holder = this.el.querySelector(HOLDER);
    if (!holder || holder.querySelector(PREVIEW)) return;

    const said = (name) => holder.getAttribute(`data-${name}`) || "";
    const label = said("label");

    const option = (action, value) => {
      const text = said(`${value}-text`);
      const pressed = String(this.el.getAttribute(`data-frame-${action}`) === value);
      const attributes = {
        type: "button",
        "data-role": "doc-example-option",
        "data-action": action,
        "data-value": value,
        "aria-pressed": pressed,
      };

      return action === "dir"
        ? element("button", attributes, [
            element("span", { "data-role": "doc-example-option-text" }, [text]),
          ])
        : element("button", { ...attributes, title: text }, [
            icon(value),
            element("span", { "data-role": "doc-example-option-text" }, [text]),
          ]);
    };

    const group = (action) =>
      element(
        "div",
        { "data-role": "doc-example-group", "data-group": action, role: "group" },
        CHOICES[action].map((value) => option(action, value))
      );

    const close = element(
      "button",
      { type: "button", "data-role": "doc-example-close", title: said("close-text") },
      [icon("close"), element("span", { "data-role": "doc-example-close-text" }, [said("close-text")])]
    );

    const frame = document.createElement("iframe");
    frame.setAttribute("data-role", "doc-example-frame");
    frame.setAttribute("sandbox", "allow-scripts allow-same-origin allow-forms");
    frame.setAttribute("title", said("frame-label"));
    if (said("src") !== "") frame.setAttribute("data-src", said("src"));

    holder.append(
      element(
        "dialog",
        { id: `${this.el.id}-preview`, "data-role": "doc-example-preview", "aria-label": label },
        [
          element("div", { "data-role": "doc-example-preview-head" }, [
            element("p", { "data-role": "doc-example-preview-title" }, [label]),
            element(
              "div",
              {
                "data-role": "doc-example-preview-toolbar",
                role: "toolbar",
                "aria-label": said("toolbar-label"),
              },
              [group("theme"), group("device"), group("dir"), close]
            ),
          ]),
          element("div", { "data-role": "doc-example-preview-stage" }, [
            element("div", { "data-role": "doc-example-viewport" }, [frame]),
          ]),
        ]
      )
    );

    this.attach();
  },

  // The preview opened, its frame handed the page that draws the example, hidden until it is dressed.
  open() {
    this.attach();
    if (!this.preview) this.build();
    if (!this.preview || this.preview.open) return;

    const frame = this.frame;
    const src = frame && frame.getAttribute("data-src");

    if (frame && src && !frame.hasAttribute("src")) {
      frame.style.visibility = "hidden";
      frame.setAttribute("src", src);
    }

    this.preview.showModal();
    this.fit();
  },

  close() {
    if (this.preview && this.preview.open) this.preview.close();
  },

  // The frame's `src` taken away and its page sent to `about:blank`, which stops everything it ran.
  unload() {
    const frame = this.frame;
    if (this.inside) this.inside.disconnect();
    this.inside = null;
    if (!frame || !frame.hasAttribute("src")) return;

    frame.removeAttribute("src");
    if (frame.contentWindow) frame.contentWindow.location.replace("about:blank");
  },

  // The frame's page once it has loaded: dressed, measured, and shown.
  loaded() {
    const frame = this.frame;
    if (!frame || !frame.hasAttribute("src")) return;

    this.dress();
    frame.style.visibility = "";
  },

  // The page the frame was handed, once it is the one loaded in it.
  page() {
    const frame = this.frame;
    const page = frame && frame.hasAttribute("src") ? frame.contentDocument : null;

    return page && page.documentElement && page.body && page.URL !== "about:blank" ? page : null;
  },

  dress() {
    const page = this.page();
    if (!page) return;

    const root = page.documentElement;
    const theme = this.el.getAttribute("data-frame-theme");
    const dir = this.el.getAttribute("data-frame-dir");

    if (CHOICES.theme.includes(theme)) root.setAttribute("data-theme", theme);
    if (CHOICES.dir.includes(dir)) root.setAttribute("dir", dir);

    if (!this.dressed.has(page)) {
      this.dressed.add(page);
      page.addEventListener("click", this.onFollow, true);
      this.observe(page);
    }

    this.fit();
  },

  // The example in the frame's page watched for its size, by an observer of that page's own window.
  observe(page) {
    if (this.inside) this.inside.disconnect();

    const view = page.defaultView;
    const live = page.querySelector(LIVE);

    this.inside =
      view && live && typeof view.ResizeObserver === "function"
        ? new view.ResizeObserver(() => this.fit())
        : null;

    if (this.inside) this.inside.observe(live);
    if (page.fonts) page.fonts.ready.then(() => this.fit());
  },

  // The frame drawn at its device's width, as tall as the example in it or the stage, whichever is
  // taller, and scaled down to the width inside the preview's padding when it is wider.
  fit() {
    const frame = this.frame;
    const viewport = this.el.querySelector(VIEWPORT);
    if (!frame || !viewport || !this.stage || !this.preview || !this.preview.open) return;

    const width = WIDTHS[this.el.getAttribute("data-frame-device")] || WIDTHS.desktop;
    frame.setAttribute("width", String(width));

    const box = window.getComputedStyle(this.stage);
    const room =
      this.stage.clientWidth - parseFloat(box.paddingLeft || "0") - parseFloat(box.paddingRight || "0");
    const shown =
      this.stage.clientHeight - parseFloat(box.paddingTop || "0") - parseFloat(box.paddingBottom || "0");
    const scale = room > 0 && room < width ? room / width : 1;

    const height = Math.max(Math.ceil(this.tall()), Math.floor(shown / scale), 1);
    frame.setAttribute("height", String(height));

    frame.style.transform = scale < 1 ? `scale(${scale})` : "";
    viewport.style.width = `${Math.floor(width * scale)}px`;
    viewport.style.height = `${Math.floor(height * scale)}px`;
  },

  // How far down the frame's page the example reaches: the bottom of its
  // `[data-role="doc-example-live"]`, else of the page's body; 0 before the page has loaded.
  tall() {
    const page = this.page();
    if (!page) return 0;

    const drawn = page.querySelector(LIVE) || page.body;
    const view = page.defaultView;

    return drawn.getBoundingClientRect().bottom + ((view && view.scrollY) || 0);
  },

  collapse(height) {
    if (!(height > 0)) return;

    const limit = Number(this.el.getAttribute("data-collapse-height")) || 0;
    const collapsible = limit > 0 && height > limit;
    if (collapsible === this.el.hasAttribute("data-collapsible")) return;

    if (collapsible) {
      this.js().setAttribute(this.el, "data-collapsible", "true");
    } else {
      this.js().removeAttribute(this.el, "data-collapsible");
    }
  },

  toggle(expand) {
    const js = this.js();

    if (this.el.hasAttribute("data-expanded")) {
      js.removeAttribute(this.el, "data-expanded");
      js.setAttribute(expand, "aria-expanded", "false");
      if (this.el.getBoundingClientRect().top < 0) this.el.scrollIntoView({ block: "start" });
    } else {
      js.setAttribute(this.el, "data-expanded", "true");
      js.setAttribute(expand, "aria-expanded", "true");
    }
  },

  // A link in the frame's page that leads to another page, followed by the page itself.
  follow(event) {
    const target = event.target;
    const link = target && typeof target.closest === "function" ? target.closest("a[href]") : null;
    if (!link || event.defaultPrevented || link.hasAttribute("phx-click")) return;

    const href = (link.getAttribute("href") || "").trim();
    if (href === "" || href.startsWith("#") || /^javascript:/i.test(href)) return;

    event.preventDefault();
    event.stopPropagation();

    const url = new URL(link.href);
    const blank = link.getAttribute("target") === "_blank";
    this.close();

    if (blank) {
      window.open(url.href, "_blank", "noopener");
    } else if (url.origin === window.location.origin) {
      this.js().navigate(url.pathname + url.search + url.hash);
    } else {
      window.location.assign(url.href);
    }
  },
};

export default DocExample;

// Keeps a document's contents where the reader left them across pages.
//
// `doc-sidebar` mounts this on its root. The contents scroll in a box: the root's nearest ancestor,
// or the root itself, whose `overflow-y` scrolls. A live navigation draws the next page, that box
// with it, at its top; this puts the new box back where the reader left the last one, then brings
// the entry the reader is on (`[aria-current="page"]`) into it when it lies outside, and moves
// nothing when it is already in view. With no box of its own the contents scroll with the page, and
// the hook does nothing.
//
// The position lives in `sessionStorage`, one per tab, per contents block (the root's `id`) and per
// document (the root's `data-document`), so it also survives a full page load, and the contents of
// another document open at their top. It is written at most once a frame while the box scrolls, and
// not while the block draws no entries (loading, failed, or filtered to nothing), when the box has
// shrunk under the reader; the position is put back when the entries are drawn again. Without
// storage the entry the reader is on is still brought into view. Only `scrollTop` is written: no
// class, no style attribute and no markup.
const SCROLL_KEY = "doc-sidebar:scrollTop:";
const ITEMS = '[data-role="doc-sidebar-items"]';
const ACTIVE = '[aria-current="page"]';
const MARGIN = 24;

function scrollingBox(el) {
  for (let node = el; node && node !== document.body; node = node.parentElement) {
    if (/^(auto|scroll|overlay)$/.test(getComputedStyle(node).overflowY)) return node;
  }

  return null;
}

const DocSidebarScroll = {
  mounted() {
    this.box = scrollingBox(this.el);
    this.frame = null;
    this.shown = false;

    if (!this.box) return;

    this.onScroll = () => {
      if (this.frame !== null) return;

      this.frame = requestAnimationFrame(() => {
        this.frame = null;

        // A block already swapped out, or one drawing no entries, reads a position the reader never left.
        if (!this.el.isConnected || !this.shown) return;

        try {
          sessionStorage.setItem(this.key(), String(this.box.scrollTop));
        } catch (_denied) {
          // Without storage the position is simply not kept.
        }
      });
    };

    this.box.addEventListener("scroll", this.onScroll, { passive: true });
    this.settle();
  },

  updated() {
    if (this.box) this.settle();
  },

  destroyed() {
    if (!this.box) return;

    this.box.removeEventListener("scroll", this.onScroll);
    if (this.frame !== null) cancelAnimationFrame(this.frame);
  },

  key() {
    return SCROLL_KEY + this.el.id + ":" + (this.el.getAttribute("data-document") || "");
  },

  settle() {
    const shown = this.el.querySelector(ITEMS) !== null;

    if (shown && !this.shown) this.restore();
    this.shown = shown;
  },

  restore() {
    let saved = null;

    try {
      saved = sessionStorage.getItem(this.key());
    } catch (_denied) {
      // Private browsing may refuse sessionStorage; the active entry is still shown below.
    }

    const top = saved === null ? NaN : parseInt(saved, 10);

    if (!Number.isNaN(top)) this.box.scrollTo({ top, behavior: "instant" });
    this.reveal();
  },

  reveal() {
    const active = this.el.querySelector(ACTIVE);
    if (!active) return;

    const view = this.box.getBoundingClientRect();
    // A box drawn nowhere, a closed drawer at display: none, has nothing to scroll into view.
    if (view.height === 0) return;

    const item = active.getBoundingClientRect();
    const top = Math.max(view.top, 0);
    const bottom = Math.min(view.bottom, window.innerHeight);
    let by = 0;

    if (item.top < top) {
      by = item.top - top - MARGIN;
    } else if (item.bottom > bottom) {
      by = item.bottom - bottom + MARGIN;
    }

    if (by !== 0) this.box.scrollTo({ top: this.box.scrollTop + by, behavior: "instant" });
  },
};

export default DocSidebarScroll;

// Keeps the address bar in step with the tab pressed on a document page.
//
// `doc-section` mounts this on its tab bar. A tab is a button carrying the address of the page with
// that tab in its URL, `data-href`, and pressing it sends the block an event, so the page is neither
// navigated nor read again. This writes that address over the one in the address bar, as the same
// history entry, so a reload or a shared link opens that tab and the back button still leaves the
// page. The hook writes no class, no style attribute and no markup.
const TAB = '[data-role="doc-tab"]';

const DocTabs = {
  mounted() {
    this.onClick = (event) => {
      const tab = event.target instanceof Element ? event.target.closest(TAB) : null;
      const href = tab && this.el.contains(tab) ? tab.getAttribute("data-href") : null;
      if (!href) return;

      const url = new URL(href, window.location.href);
      if (url.origin !== window.location.origin) return;

      window.history.replaceState(window.history.state, "", url.pathname + url.search);
    };

    this.el.addEventListener("click", this.onClick);
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
  },
};

export default DocTabs;

stylesheets.content:
/* Code in a documentation page: <pre class="highlight"><code class="language-x"> with one <span>
   per token. The token classes are the ones Makeup emits, coloured in its Monokai style. */
pre.highlight {
  color: #f8f8f2;
  background-color: #272822;
  border-radius: 12px;
  padding: 16px 20px;
  margin: 0 0 12px;
  overflow-x: auto;
  font-size: 13px;
  line-height: 1.6;
  direction: ltr;
  text-align: left;
  tab-size: 2;
}

pre.highlight code {
  display: block;
  padding: 0;
  background: transparent;
  color: inherit;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: inherit;
  white-space: pre;
}

/* The window doc-section draws each code block in: a head holding the block's language and a button
   that copies its code, over the block. The button carries data-copied for a moment once the code
   is copied; doc-code-status is what a screen reader is told. */
[data-role="doc-code"] {
  margin: 0 0 12px;
  border-radius: 12px;
  background-color: #272822;
  overflow: hidden;
  direction: ltr;
  text-align: left;
}

[data-role="doc-code"] > pre {
  margin: 0;
  border-radius: 0;
}

[data-role="doc-code-head"] {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 8px 20px;
  border-bottom: 1px solid rgba(248, 248, 242, 0.1);
  color: #a59f85;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  line-height: 1.5;
}

[data-role="doc-code-lang"] {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

[data-role="doc-code-copy"] {
  display: inline-flex;
  align-items: center;
  margin-left: auto;
  padding: 2px 10px;
  border: 1px solid rgba(248, 248, 242, 0.2);
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

[data-role="doc-code-copy"]:hover {
  border-color: rgba(248, 248, 242, 0.45);
  color: #f8f8f2;
}

[data-role="doc-code-copy"]:focus-visible {
  outline: 2px solid #66d9ef;
  outline-offset: 2px;
}

[data-role="doc-code-copied-text"] {
  display: none;
  align-items: center;
  gap: 0.4em;
}

[data-role="doc-code-copy"][data-copied] {
  border-color: #a6e22e;
  color: #a6e22e;
}

[data-role="doc-code-copy"][data-copied] [data-role="doc-code-copy-text"] {
  display: none;
}

[data-role="doc-code-copy"][data-copied] [data-role="doc-code-copied-text"] {
  display: inline-flex;
}

[data-role="doc-code-status"] {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* The frame doc-example draws an example in, and the preview its hook builds: the head over the
   example, its toolbars and their buttons, the foot under a cut example, and the dialog with its
   own head, its stage and the viewport its frame is scaled in. Each part is keyed on its data-role
   and holds no class of its own; the layer keeps every rule a site writes without one above it. */
@layer components {
  [data-role="doc-example"] {
    @apply relative my-5 rounded-[14px] border border-[#ecebe6] bg-white text-[#1b1a18] dark:border-[#34323b] dark:bg-[#18171c];
  }

  [data-role="doc-example-head"] {
    @apply flex flex-wrap items-center gap-x-3 gap-y-2 rounded-t-[14px] border-b border-[#ecebe6] bg-[#fbfbf9] px-3 py-2 dark:border-[#34323b];
  }

  [data-role="doc-example-preview-head"] {
    @apply flex flex-wrap items-center gap-x-3 gap-y-2 border-b border-[#ecebe6] bg-[#fbfbf9] px-3 py-2;
  }

  [data-role="doc-example-title"],
  [data-role="doc-example-preview-title"] {
    @apply min-w-0 text-xs leading-snug font-semibold text-[#3a382f];
  }

  [data-role="doc-example-toolbar"],
  [data-role="doc-example-preview-toolbar"] {
    @apply ms-auto flex flex-wrap items-center gap-2;
  }

  [data-role="doc-example-group"] {
    @apply flex items-center gap-1;
  }

  [data-role="doc-example-option"],
  [data-role="doc-example-open"],
  [data-role="doc-example-close"] {
    @apply inline-flex h-7 min-w-7 cursor-pointer items-center justify-center gap-1 rounded-md border border-[#ecebe6] bg-white px-1.5 text-[11px] font-semibold tracking-[0.04em] text-[#6d6a63] uppercase hover:border-[#5b57d6] hover:text-[#5b57d6] aria-pressed:border-[#5b57d6] aria-pressed:bg-[#f2f1fc] aria-pressed:text-[#5b57d6];
  }

  [data-role="doc-example-icon"] {
    @apply size-4;
  }

  [data-role="doc-example-option"]:is([data-action="theme"], [data-action="device"]) > [data-role="doc-example-option-text"],
  [data-role="doc-example-close-text"] {
    @apply sr-only;
  }

  [data-role="doc-example-stage"] {
    @apply rounded-b-[14px];
  }

  [data-role="doc-example-expand"] {
    @apply rounded-full border border-[#ecebe6] bg-white px-3 py-1 text-xs font-semibold text-[#3a382f] hover:border-[#5b57d6] hover:text-[#5b57d6] dark:border-[#34323b] dark:bg-[#18171c] dark:text-[#c9c6bf];
  }

  [data-role="doc-example-preview"] {
    @apply m-auto h-[calc(100dvh-2rem)] w-[min(1180px,calc(100vw-2rem))] max-w-none overflow-hidden rounded-[14px] border border-[#ecebe6] bg-white p-0 text-[#1b1a18] shadow-2xl backdrop:bg-black/60 open:flex open:flex-col;
  }

  [data-role="doc-example-preview-stage"] {
    @apply min-h-0 flex-1 overflow-auto bg-white [scrollbar-gutter:stable];
  }

  [data-role="doc-example"][data-frame-theme="dark"] [data-role="doc-example-preview-stage"] {
    @apply bg-[#18171c];
  }

  [data-role="doc-example-viewport"] {
    @apply mx-auto overflow-hidden;
  }

  [data-role="doc-example-frame"] {
    @apply block max-w-none origin-top-left border-0 bg-transparent;
  }
}

/* A long code block, and a tall example, cut at their data-collapse-lines and data-collapse-height
   until the button under them shows all of it: the cut lines fade out under a light blur, with the
   button on the fade. data-expanded draws it whole, the button under it. */
[data-role="doc-code"][data-collapsible] {
  position: relative;
}

[data-role="doc-code"][data-collapsible]:not([data-expanded]) > pre {
  overflow-y: hidden;
}

[data-role="doc-code"][data-collapse-lines="8"]:not([data-expanded]) > pre { max-height: calc(8lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="12"]:not([data-expanded]) > pre { max-height: calc(12lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="16"]:not([data-expanded]) > pre { max-height: calc(16lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="20"]:not([data-expanded]) > pre { max-height: calc(20lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="24"]:not([data-expanded]) > pre { max-height: calc(24lh + 1.25em); }
[data-role="doc-code"][data-collapse-lines="32"]:not([data-expanded]) > pre { max-height: calc(32lh + 1.25em); }

[data-role="doc-example"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] {
  overflow-y: clip;
}

[data-role="doc-example"][data-collapse-height="240"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 240px; }
[data-role="doc-example"][data-collapse-height="320"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 320px; }
[data-role="doc-example"][data-collapse-height="400"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 400px; }
[data-role="doc-example"][data-collapse-height="480"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 480px; }
[data-role="doc-example"][data-collapse-height="640"][data-collapsible]:not([data-expanded]) [data-role="doc-example-stage"] { max-height: 640px; }

[data-role="doc-code-foot"],
[data-role="doc-example-foot"] {
  display: flex;
  justify-content: center;
  padding: 8px 12px 12px;
}

[data-role="doc-example"]:not([data-collapsible]) [data-role="doc-example-foot"] {
  display: none;
}

[data-role="doc-code"][data-collapsible]:not([data-expanded]) > [data-role="doc-code-foot"],
[data-role="doc-example"][data-collapsible]:not([data-expanded]) [data-role="doc-example-foot"] {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding-top: 64px;
  background: linear-gradient(to bottom, rgba(39, 40, 34, 0), #272822 70%);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 40%);
  mask-image: linear-gradient(to bottom, transparent, #000 40%);
}

[data-role="doc-example"][data-collapsible]:not([data-expanded]) [data-role="doc-example-foot"] {
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0), #ffffff 70%);
}

[data-theme="dark"] [data-role="doc-example"][data-collapsible]:not([data-expanded]) [data-role="doc-example-foot"] {
  background: linear-gradient(to bottom, rgba(24, 23, 28, 0), #18171c 70%);
}

[data-role="doc-code-expand"] {
  padding: 3px 12px;
  border: 1px solid rgba(248, 248, 242, 0.2);
  border-radius: 9999px;
  background: #272822;
  color: #a59f85;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}

[data-role="doc-code-expand"]:hover {
  border-color: rgba(248, 248, 242, 0.45);
  color: #f8f8f2;
}

[data-role="doc-code-expand"]:focus-visible,
[data-role="doc-example-expand"]:focus-visible {
  outline: 2px solid #66d9ef;
  outline-offset: 2px;
}

[data-role="doc-code-collapse-text"],
[data-role="doc-example-collapse-text"] {
  display: none;
}

[data-role="doc-code"][data-expanded] [data-role="doc-code-expand-text"],
[data-role="doc-example"][data-expanded] [data-role="doc-example-expand-text"] {
  display: none;
}

[data-role="doc-code"][data-expanded] [data-role="doc-code-collapse-text"],
[data-role="doc-example"][data-expanded] [data-role="doc-example-collapse-text"] {
  display: inline;
}

